#include <bits/stdc++.h>
using namespace std;

class Fibonacci {
    long long mod;
    map<long long, long long> calculatedNumbers;
public:
    Fibonacci(long long mod) : mod(mod) {
        calculatedNumbers[0] = 1;
        calculatedNumbers[1] = 1;
    }

    long long fib(long long n) {
        auto it = calculatedNumbers.find(n);
        if (it != calculatedNumbers.end()) return it->second;

        long long k = n / 2;
        long long res;
        if (n % 2 == 0) {
            res = (fib(k) * fib(k) + fib(k - 1) * fib(k - 1)) % mod;
        } else {
            res = (fib(k) * fib(k + 1) + fib(k - 1) * fib(k)) % mod;
        }
        calculatedNumbers[n] = res;
        return res;
    }
};

class Exponentation {
public:
    static long long calc(long long a, long long b, long long m) {
        if (b == 0) return 1 % m;
        long long half = calc(a, b / 2, m);
        half = (half * half) % m;
        if (b % 2 == 0) return half;
        else return (a * half) % m;
    }
};

class Solver {
    long long n, k, l, MOD;
public:
    void read() {
        cin >> n >> k >> l >> MOD;
    }

    void solve() {
        read();
        if (l < 64 && ((1ULL << l) - 1 < (unsigned long long)k)) {
            cout << 0 << endl;
            return;
        }

        long long zeroPos = Fibonacci(MOD).fib(n + 1);
        long long onePos = Exponentation::calc(2, n, MOD) - zeroPos;
        onePos %= MOD;
        if (onePos < 0) onePos += MOD;

        long long res = 1 % MOD;
        for (int i = 0; i < l; i++) {
            if (k & (1LL << i)) res = (res * onePos) % MOD;
            else res = (res * zeroPos) % MOD;
        }
        cout << res % MOD << endl;
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    Solver solver;
    solver.solve();
    return 0;
}

