		n = in.nextLong();
		k = in.nextLong();
		l = in.nextLong();
		MOD = in.nextLong();
	}

	public void solve(InputReader in, PrintWriter out){
		read(in);
		if(l != 64 && (1l << l)-1 < k){
			out.println(0);
			return;
		}

		long zeroPos = new Fibonacci(MOD).fib(n+1);
		long onePos = Exponentation.calc(2, n, MOD)-zeroPos;
		while(onePos < 0) onePos += MOD;

		long res = 1;
		for(int i=0; i<l; i++){
			if((k & (1l << i)) != 0) res *= onePos;
			else res *= zeroPos;
			res %= MOD;
		}
		out.println(res%MOD);
	}
}

class InputReader {
	public BufferedReader reader;
	String currentLine[];
	int token;

	public InputReader(InputStream stream) {
		reader = new BufferedReader(new InputStreamReader(stream), 32768);
		currentLine = null;
		token = 0;
	}

	public String next(){
		while (currentLine == null || token >= currentLine.length) {
			try {
				currentLine = reader.readLine().split("\\s+");
				token = 0;
			} catch (IOException e) {
				e.printStackTrace();
			}
		}
		return currentLine[token++];
	}

	public int nextInt() {
		return Integer.parseInt(next());
	}

	public long nextLong(){
		return Long.parseLong(next());
	}
}
